def lps(s):
    """
    Finds the length of the longest palindromic subsequence in the given string.

    :param s: Input string
    :return: Length of the longest palindromic subsequence
    """
    def lps_util(s, i, j):
        if i > j:
            return 0
        if i == j:
            return 1
        if s[i] == s[j]:
            return 2 + lps_util(s, i+1, j-1)
        else:
            return max(lps_util(s, i+1, j), lps_util(s, i, j-1))

    return lps_util(s.replace(" ", ""), 0, len(s.replace(" ", ""))-1)

