def group_tuples(lst):
    from collections import defaultdict
    grouped = defaultdict(list)
    for key, value in lst:
        if key in grouped:
            grouped[key].append(value)
        else:
            grouped[key] = [value]
    result = []
    for key, values in grouped.items():
        if key:
            result.append((key,) + tuple(values))
    return result

