def Find_Max(lst):
    # Find the element of a list having maximum length.
    if not lst:
        return []

    max_len = -1
    max_elem = []
    for item in lst:
        if len(item) > max_len:
            max_len = len(item)
            max_elem = item
    return max_elem + [max_len - len(max_elem)]
